def countComponents(nums, threshold):
    n = len(nums)
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu != pv:
            parent[pu] = pv

    # Key fact: if a | L and b | L with L <= threshold, then lcm(a, b) | L <= threshold,
    # so a and b are connected. Thus for every L <= threshold, all of nums's divisors
    # of L form one component. Numbers > threshold can never form an edge (lcm >= value),
    # so they stay isolated.
    rep = [-1] * (threshold + 1)  # rep[L] = index of a num value dividing L
    for i, x in enumerate(nums):
        if x > threshold:
            continue
        for L in range(x, threshold + 1, x):
            if rep[L] == -1:
                rep[L] = i
            else:
                union(i, rep[L])

    return len(set(find(i) for i in range(n)))
